candidates = grasp_candidates("blue_pen")
best_candidate = None
best_score = -1
for c in candidates:
    if c["source"] == "geometry" and abs(c["yaw"] - (0.686)) < 0.1 and abs(c["height"] - 0.0119) < 0.005:
        if c["score"] > best_score:
            best_score = c["score"]
            best_candidate = c
if best_candidate is None:
    best_candidate = candidates[0]

grasp_result = grasp(best_candidate)
if not grasp_result["holding_something"]:
    raise RuntimeError("Failed to grasp blue_pen")

spots = free_spots("green_case", "blue_pen")
target_spot = None
for spot in spots["spots"]:
    if abs(spot["object_long_axis_yaw"] - spots["long_axis_yaw"]) < 0.1:
        target_spot = spot
        break
if target_spot is None:
    target_spot = spots["spots"][0]

carry_to(target_spot["x"], target_spot["y"], height=0.18, yaw=spots["long_axis_yaw"])
lower_until_contact()
open_gripper()
retreat()
check("blue_pen", "green_case")

